const {test}=require('node:test'),assert=require('node:assert/strict'),store=require('../local-species.cjs'),E=require('../dist/engine.js');
const all=Array.from({length:10},(_,i)=>store.species(3001+i));
test('3001–3010全部独立本地存档且多精灵词条可见延期',()=>{assert.equal(all.length,10);for(const s of all){assert.deepEqual(store.issues(s),[]);assert.equal(s.source.storage,'local');}const m=all[0].moves.find(m=>m.id===19142);assert.ok(E.WIKI.compile(m,all[0]).deferred.some(x=>x.effectId===873));});
for(const source of all)test(`${source.id} ${source.name}：本地全部技能与不同对手结算`,()=>{const opponent=all[(source.id-3001+1)%10];for(const m of source.moves){assert.equal(E.WIKI.moveIssue(m,source),'',m.name);const selected=E.WIKI.defaultMoves(source);if(!selected.includes(m.id))selected[selected.findIndex(id=>!source.moves.find(x=>x.id===id).fifth)]=m.id;const s=E.createBattle({wikiSnapshots:[source,opponent],wikiLoadouts:[selected,E.WIKI.defaultMoves(opponent)],criticals:false,builds:[{overrides:{maxHp:9999,atk:100,spa:100,spe:900}},{overrides:{maxHp:9999,def:400,spd:400}}]});const t=E.resolveTurn(s,['wiki:'+m.id,s.fighters[1].moves[0]]);assert.ok(t.fighters.every(f=>Number.isFinite(f.hp)&&f.hp>=0&&f.hp<=f.stats.maxHp),m.name);assert.ok(t.fighters.every(f=>Object.values(f.pp).every(p=>p>=0)));assert.equal(s.round,1);assert.deepEqual(E.createBattle(s.initial).fighters,s.fighters);if(m.id===13224)assert.equal(t.turns[0].events.filter(e=>e.detail.includes('威力 90')).length,1);}});

