function context(a,t,random=()=>0){const events=[];return {a,t,round:1,m:{kind:'status',name:'测试技能'},random,emit:x=>events.push(x),name:f=>f===a?'A':'B',heal:(f,n)=>{f.hp=Math.min(f.stats.maxHp,f.hp+Math.floor(n));},hurt:(f,n)=>{const v=Math.min(f.hp,Math.floor(n));f.hp-=v;return v;},stage:(f,n,keys)=>{for(const k of keys??Object.keys(f.stages))f.stages[k]+=n;},timed:(f,k,n,d,start=1)=>{f.effects[k]={start,end:start+n-1,...d};},clear:(f)=>{const had=Object.keys(f.effects).length>0;f.effects={};return had;},clearBoost:()=>false,ailment:(f,k)=>{f.ailments[k]=2;return true;},events};}

