const effects=require('../dist/effect-registry.js');
const source=require('../data/species/3577.json').snapshot;
const soul=E.SOULS.registry[881];
function fighter(hp=700){return {hp,stats:{maxHp:1000},soulState:{},stages:{atk:0,def:0,spa:0,spd:0,spe:0,acc:0},ailments:{},effects:{},counts:{},side:0,moves:['a','b'],pp:{a:3,b:2}};}
function context(a,t,random=()=>0){const events=[];return {a,t,round:1,m:{kind:'physical',name:'测试技能'},random,emit:x=>events.push(x),name:f=>f===a?'A':'B',on:(f,k)=>!!f.effects[k]&&f.effects[k].start<=1&&f.effects[k].end>=1,heal:(f,n)=>{f.hp=Math.min(f.stats.maxHp,f.hp+Math.floor(n));},hurt:(f,n)=>{const v=Math.min(f.hp,Math.floor(n));f.hp-=v;return v;},stage:(f,n,keys)=>{for(const k of keys??Object.keys(f.stages))f.stages[k]=Math.max(-6,Math.min(6,f.stages[k]+n));},boost:(f,n)=>{for(const k of Object.keys(f.stages))f.stages[k]+=n;},timed:(f,k,n,d,start=1)=>{f.effects[k]={start,end:start+n-1,...d};},clear:(f)=>{const had=Object.keys(f.effects).length>0;f.effects={};return had;},clearBoost:(f)=>{const had=Object.values(f.stages).some(n=>n>0);for(const k of Object.keys(f.stages))if(f.stages[k]>0)f.stages[k]=0;return had;},ailment:(f,k)=>{f.ailments[k]=2;return true;},events};}
function rule(id){const move=source.moves.find(m=>m.effectIds.includes(id));return effects.compileInstances(move.effectInstances.filter(x=>x.id===id),source.effects);}

test('3577 快照、魂印881、光战斗属性和第五技能来源通过核对',()=>{assert.equal(source.souls[0].id,881);assert.equal(source.souls[0].hash,soul.sourceHash);assert.deepEqual(source.typeChart.aliases['光战斗'],['光','战斗']);assert.equal(source.moves.filter(m=>m.fifth).length,1);});
