    assert.equal(turn(make(e)).fighters[1].effects[id===988?'skillBlock':'attackBlock'],undefined);
    const st=make(e,{opponentBoost:true});st.fighters[1].stages.atk=1;const b=turn(turn(st),IDLE,900023);assert.equal(b.fighters[1].stages.atk,id===988?0:2);
