 for(let i=0;i<pool.length;i++)for(const offset of [.01,.25,.5,.75,.99]){const [choice]=P.draw(1,sequence([(i+offset)/pool.length,0]));assert.equal(choice.id,pool[i].id);counts.set(choice.id,counts.get(choice.id)+1);}
