const {test}=require('node:test');const assert=require('node:assert/strict');const R=require('../dist/effect-registry.js');const S=require('../dist/soul-registry.js');
const examples={1:'给予对方损伤的一半会回复自己的体力',2:'对方体力小于1/2时威力加倍',3:'解除自身的能力下降状态',4:'技能使用成功时，100%改变自身攻击等级+1',5:'技能使用成功时，25%改变对手防御等级-2',6:'对方所受伤害的1/4会反弹给自己',8:'伤害大于对方体力时，对方会余下1体力',43:'恢复自身最大体力的1/2',57:'3回合内每回合使用技能恢复自身最大体力的1/3',101:'给对手造成伤害时，伤害数值的50%恢复自身体力',191:'4回合内免疫并反弹所有受到的异常状态',760:'攻击时造成的伤害不会出现微弱（克制关系为微弱时都变成普通）',821:'2回合内自身的回合类效果无法被消除，后出手时回合数+1',842:'若自身处于能力提升状态则造成的攻击伤害额外提升50%',913:'消除对手回合类效果，消除成功则下回合自身造成的攻击伤害额外提升100%',946:'全属性+1，若自身当前体力低于对手则强化效果翻倍',983:'未击败对手则自身全属性+1',984:'未击败对手则下回合自身所有技能先制+2'};
function compile(ids,description=ids.map(id=>examples[id]).join('；')){return R.compile(ids,description,ids.map(id=>({id,argsNum:R.registry[id].argsNum,template:R.registry[id].template})));}
function context(){return {a:{side:0,hp:60,stats:{maxHp:200},stages:{atk:1,def:-2}},t:{hp:40,stats:{maxHp:100},stages:{}},m:{name:'组合技能'},power:50,affinity:.5,modifier:1,first:1,round:2,emit:()=>{},name:()=>'',random:()=>0,calls:[],heal(f,n){this.calls.push(['heal',n]);},hurt(f,n){this.calls.push(['hurt',n]);},stage(f,n,keys){this.calls.push(['stage',n,keys]);},timed(f,k,n,data,start){this.calls.push(['timed',k,n,data,start]);},clear(){return true;},dealt:100};}
test('所有注册ID编译为带参数与阶段的指令，完整组合可执行',()=>{const ids=Object.keys(examples).map(Number),out=compile(ids);assert.equal(out.issue,'');assert.equal(out.operations.length,18);const c=context();R.run('beforeDamage',out.operations,c);assert.equal(c.power,100);assert.equal(c.affinity,1);assert.equal(c.modifier,1.5);assert.equal(c.leaveOne,true);R.run('afterHit',out.operations,c);assert.equal(c.a.stages.def,0);assert.ok(c.calls.some(x=>x[0]==='hurt'&&x[1]===25));assert.ok(c.calls.some(x=>x[1]==='protect'&&x[2]===3));});
test('重复ID保留参数和顺序，禁止只执行已认识的半条技能',()=>{const out=compile([4,4],'技能使用成功时，100%改变自身攻击等级+1；技能使用成功时，100%改变自身防御等级-2');assert.deepEqual(out.operations.map(x=>x.params.stat),['atk','def']);assert.deepEqual(out.operations.map(x=>x.params.amount),[1,-2]);const c=context();R.run('afterHit',out.operations,c);assert.deepEqual(c.calls,[['stage',1,['atk']],['stage',-2,['def']]]);for(const text of [examples[4]+'；消除对手强化','未知前缀'+examples[4],examples[4]+'；'+examples[4]])assert.ok(compile([4],text).issue);});
test('模板变化、未注册ID与参数越界均拒绝编译',()=>{assert.ok(R.compile([999],'任意效果',[]).issue);assert.ok(R.compile([1],examples[1],[{id:1,argsNum:0,template:examples[1]+'并回复PP'}]).issue);assert.ok(compile([43],'恢复自身最大体力的1/0').issue);assert.ok(compile([4],'技能使用成功时，101%改变自身攻击等级+1').issue);assert.ok(compile([57],'0回合内每回合使用技能恢复自身最大体力的1/3').issue);});
test('条件增伤严格半血，消回合失败不增伤，击败目标不给未击败奖励',()=>{const c=context();c.t.hp=50;R.run('beforeDamage',compile([2]).operations,c);assert.equal(c.power,50);c.clear=()=>false;R.run('afterHit',compile([913]).operations,c);assert.deepEqual(c.calls,[]);c.t.hp=0;R.run('afterHit',compile([983,984]).operations,c);assert.deepEqual(c.calls,[]);});
test('魂印ID与技能ID分开注册，未知魂印没有默认效果',()=>{assert.equal(S.trait({soulId:622},'pinkImmune'),true);assert.equal(S.trait({soulId:3},'pinkImmune'),undefined);assert.equal(R.registry[3].phase,'afterHit');assert.equal(S.registry[3].traits.attackReduction,.1);assert.equal(S.trait({species:'emperor',soulId:527},'pinkImmune'),undefined);});
test('王雷伊第五实际使用四个ID组合，强化与次回合奖励不重复触发',()=>{const E=require('../dist/engine.js');const s=E.createBattle({species:['bubuhua','king'],criticals:false,stats:[{maxHp:5000},{maxHp:5000}]});s.fighters[0].effects.reflect={start:1,end:5};const t=E.resolveTurn(s,['heal','king5']);assert.deepEqual(E.MOVES.king5.operations.map(o=>o.effectId),[760,913,983,984]);assert.equal(t.fighters[1].stages.atk,1);assert.equal(t.fighters[1].effects.id913.start,2);assert.equal(t.fighters[1].effects.id984.amount,2);assert.equal(t.fighters[0].effects.reflect,undefined);assert.equal(t.fighters[1].effects.doubleDamage,undefined);});

engine.test.cjs:
const { test } = require('node:test');
const assert = require('node:assert/strict');
const E = require('../dist/engine.js');
const fresh = () => E.createBattle({ species: ['bubuhua', 'bubuhua'], criticals: false });

test('双方独立初始化，初始体力及 PP 正确', () => {
  const s = fresh();
  assert.equal(s.fighters[0].hp, 331);
  s.fighters[0].pp.crunch--;
  assert.equal(s.fighters[1].pp.crunch, 15);
  assert.notEqual(s.fighters[0].stats, s.fighters[1].stats);
});
test('缺少选招、未知技能和耗尽 PP 均被拒绝，不改变原状态', () => {
  const s = fresh(); s.fighters[0].pp.storm = 0;
  const before = JSON.stringify(s);
  for (const choices of [[null, 'heal'], ['missing', 'heal'], ['storm', 'heal'], ['struggle', 'heal']]) assert.throws(() => E.resolveTurn(s, choices));
  assert.equal(JSON.stringify(s), before);
});
test('咬碎伤害符合独立算例 74–88，双方各扣一次 PP', () => {
  const s = fresh();
  s.fighters[0].stats.spe = 200;
  const out = E.resolveTurn(s, ['crunch', 'absorb']);
  const damage = out.turns[0].events.find(e => e.kind === 'damage');
  const n = Number(damage.text.match(/损失 (\d+)/)[1]);
  assert.ok(n >= 74 && n <= 88);
  assert.equal(out.fighters[0].pp.crunch, 14);
  assert.equal(out.fighters[1].pp.absorb, 9);
  assert.equal(s.fighters[0].hp, 331);
  assert.equal(s.turns.length, 0);
});
test('相同种子和选招可完整复现，同速存在双方先手', () => {
  const play = () => { let s = fresh(); for (const c of [['crunch', 'storm'], ['heal', 'absorb'], ['storm', 'crunch']]) s = E.resolveTurn(s, c); return s; };
  assert.deepEqual(play(), play());
  const firsts = new Set();
  for (let i = 0; i < 30; i++) firsts.add(E.resolveTurn(E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: String(i) }), ['heal', 'heal']).turns[0].first);
  assert.equal(firsts.size, 2);
});
test('光合作用回复半血并封顶，满血仍消耗 PP', () => {
  const s = fresh(); s.fighters[0].hp = 1;
  const out = E.resolveTurn(s, ['heal', 'heal']);
  assert.equal(out.fighters[0].hp, 166);
  assert.equal(out.fighters[1].hp, 331);
  assert.equal(out.fighters[1].pp.heal, 4);
});
test('超级吸取按实际伤害回复，不按溢出伤害回复', () => {
  const s = fresh(); s.fighters[0].hp = 100; s.fighters[0].stats.spe = 200; s.fighters[1].hp = 10;
  const out = E.resolveTurn(s, ['absorb', 'heal']);
  assert.equal(out.fighters[0].hp, 105);
  assert.equal(out.fighters[1].hp, 0);
  assert.equal(out.fighters[1].pp.heal, 5);
});
test('击败后手后不再行动，结束后不能继续回合', () => {
  const s = fresh(); s.fighters[0].stats.spe = 200; s.fighters[1].hp = 1;
  const out = E.resolveTurn(s, ['crunch', 'crunch']);
  assert.equal(out.winner, 0); assert.equal(out.finished, true);
  assert.equal(out.fighters[1].pp.crunch, 15);
  assert.throws(() => E.resolveTurn(out, ['heal', 'heal']));
});
test('飞叶风暴命中降低特攻、未命中不降低，两者均扣 PP', () => {
  const seen = new Set();
  for (let i = 0; i < 80; i++) {
    const s = E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: `storm-${i}`, criticals: false }); s.fighters[0].stats.spe = 200;
    const out = E.resolveTurn(s, ['storm', 'heal']);
    const miss = out.turns[0].events.some(e => e.kind === 'miss'); seen.add(miss);
    assert.equal(out.fighters[0].stages.spa, miss ? 0 : -1);
    assert.equal(out.fighters[0].pp.storm, 4);
  }
  assert.equal(seen.size, 2);
});
test('特攻下降不低于 -6，咬碎可触发防御 -2', () => {
  let defenseDrop = false;
  for (let i = 0; i < 80; i++) {
    const s = E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: `stages-${i}`, criticals: false }); s.fighters[0].stages.spa = -6; s.fighters[0].stats.spe = 200;
    const out = E.resolveTurn(s, ['storm', 'crunch']);
    assert.equal(out.fighters[0].stages.spa, -6);
    if (out.fighters[0].stages.def === -2) defenseDrop = true;
  }
  assert.ok(defenseDrop);
});
test('全部 PP 耗尽才能挣扎，反伤可导致平局', () => {
  const s = fresh();
  for (const f of s.fighters) { for (const id of E.LOADOUT) f.pp[id] = 0; f.hp = 1; }
  assert.deepEqual(E.availableMoves(s.fighters[0]), ['struggle', 'potion:hp', 'potion:pp']);
  const out = E.resolveTurn(s, ['struggle', 'struggle']);
  assert.equal(out.finished, true); assert.equal(out.winner, 'draw');
  assert.deepEqual(out.fighters.map(f => f.hp), [0, 0]);
});
test('能力和种子输入校验', () => {
  for (const bad of [0, -1, 1.5, NaN, Infinity, 10000]) assert.throws(() => E.createBattle({ species: ['bubuhua', 'bubuhua'], stats: [{ atk: bad }] }));
  assert.throws(() => E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: ' ' }));
  assert.throws(() => E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: 'a'.repeat(65) }));
});
test('多组完整对局保持血量和 PP 边界并能够结束', () => {
  for (let seed = 0; seed < 30; seed++) {
    let s = E.createBattle({ species: ['bubuhua', 'bubuhua'], seed: `full-${seed}` });
    for (let round = 0; round < 100 && !s.finished; round++) {
      const choices = s.fighters.map(f => E.availableMoves(f)[0]);
      s = E.resolveTurn(s, choices);
      for (const f of s.fighters) {
        assert.ok(f.hp >= 0 && f.hp <= f.stats.maxHp);
        assert.ok(Object.values(f.pp).every(pp => pp >= 0));
      }
    }
    assert.ok(s.finished);
  }
});

