const {test}=require('node:test');const assert=require('node:assert/strict');const E=require('../dist/engine.js');
const make=(a='none',b='none')=>E.createBattle({seed:'equipment',criticals:false,builds:[{suit:a},{suit:b}],stats:[{maxHp:3000,atk:100,def:300,spe:400},{maxHp:3000,atk:100,def:300,spe:200}]});
const log=s=>s.turns.at(-1).events.map(e=>e.text).join('\n');
test('五套面板、覆盖优先与切换无累积',()=>{const base=E.calculateStats('king').stats;for(const id of Object.keys(E.GEAR.SUITS)){const g=E.calculateStats('king',{suit:id});for(const k of Object.keys(base))assert.equal(g.stats[k],base[k]+E.GEAR.suitBonus(id,k,base[k]));assert.equal(E.calculateStats('king',{suit:id,overrides:{spe:123}}).stats.spe,123);}assert.equal(E.calculateStats('king',{suit:'judgment'}).stats.atk,base.atk+60);});
test('抗性校验、55与18互斥，无额外5%',()=>{for(const resistance of [{fixed:101},{percent:-1},{critical:2.5},{major:'麻痹',minor:'麻痹'}])assert.throws(()=>E.calculateStats('king',{resistance}));const f=make().fighters[1];assert.equal(E.GEAR.resistanceChance(f,'麻痹'),0);f.build.resistance={major:'麻痹',minor:'疲惫'};assert.equal(E.GEAR.resistanceChance(f,'麻痹'),.55);assert.equal(E.GEAR.resistanceChance(f,'疲惫'),.18);});
test('三类减伤、皇免疫、无响应绕过',()=>{const s=make('none','destiny'),f=s.fighters[1];f.build.resistance={fixed:35,percent:20,critical:30};f.suitState.stacks=10;assert.equal(E.GEAR.mitigate(f,1000,'fixed'),520);assert.equal(E.GEAR.mitigate(f,1000,'percent'),640);assert.equal(E.GEAR.mitigate(f,1000,'critical'),700);assert.equal(E.GEAR.mitigate(s.fighters[0],1000,'fixed'),0);assert.equal(E.GEAR.mitigate(f,1000,'fixed',{bypass:true}),1000);});
test('皇御未受击登记、受击回血与反击',()=>{let s=E.resolveTurn(make('royal'),['gate','inherit']);assert.equal(s.fighters[0].suitState.royalFollowRound,2);s=E.resolveTurn(make('royal'),['gate','king150']);assert.match(log(s),/皇御反击/);assert.match(log(s),/皇御首回合受击/);});
test('胜天用招层数、控制额外层与上限',()=>{let s=make('destiny');s.fighters[1].ailments['疲惫']=1;s=E.resolveTurn(s,['gate','inherit']);assert.equal(s.fighters[0].suitState.stacks,2);s=make('destiny');s.fighters[0].suitState.stacks=10;s=E.resolveTurn(s,['gate','inherit']);assert.equal(s.fighters[0].suitState.stacks,10);});
test('晨曦速度、追加固伤与受击回血进入日志',()=>{const s=E.resolveTurn(make('dawn','dawn'),['emperor5','king150']);assert.match(log(s),/忽略对手 10/);assert.match(log(s),/晨曦追加/);assert.match(log(s),/晨曦受击回复/);});
test('腐蚀延迟到下一回合，免控时补偿百分比',()=>{let s=E.resolveTurn(make('none','corrosion'),['emperor5','king150']);assert.equal(s.fighters[1].suitState.corrodeRound,2);assert.doesNotMatch(log(s),/结算上回合受击/);s=E.resolveTurn(s,['gate','inherit']);assert.match(log(s),/结算上回合受击/);assert.match(log(s),/腐蚀未控补偿/);});
test('裁决首回合护罩和在场增伤锁定、减伤上限',()=>{let s=make('none','judgment');s.fighters[1].hp=900;s.fighters[1].ailments['疲惫']=1;s=E.resolveTurn(s,['gate','inherit']);assert.equal(s.fighters[1].suitState.barrier,300);assert.equal(s.fighters[1].suitState.judgmentBonus,.4);assert.equal(s.fighters[1].suitState.judgmentReduction,.25);s=E.resolveTurn(s,['gate','inherit']);assert.equal(s.fighters[1].suitState.judgmentReduction,0);assert.equal(s.fighters[1].suitState.judgmentBonus,.4);});
test('抗性随机可复现，成功免疫与失败均可出现',()=>{const seen=new Set();for(let i=0;i<50;i++){let s=make('none','corrosion');s.seed=String(i);s.rng=i;s.round=4;s.fighters[0].build.resistance.major='麻痹';s.fighters[1].suitState.corrodeRound=4;const a=E.resolveTurn(s,['gate','inherit']);assert.deepEqual(a,E.resolveTurn(s,['gate','inherit']));if(log(a).includes('成功抵抗'))seen.add('yes');if(log(a).includes('未抵抗'))seen.add('no');}assert.equal(seen.size,2);});
test('三组刻印独立合计、套装计算与最终覆盖',()=>{const inscriptions=[{maxHp:50,atk:20},{atk:30,spe:10},{atk:40,def:15}];const base=E.calculateStats('king').stats;const g=E.calculateStats('king',{inscriptions,suit:'corrosion'});assert.equal(g.stats.maxHp,base.maxHp+50);assert.equal(g.stats.atk,Math.floor((base.atk+90)*1.1));assert.equal(g.stats.spe,base.spe+10);assert.equal(E.calculateStats('king',{inscriptions,overrides:{atk:123}}).stats.atk,123);for(const inscriptions of [[{atk:-1}],[{atk:1.5}],[{spe:1000}],[{},{},{},{}]])assert.throws(()=>E.calculateStats('king',{inscriptions}));const s=E.createBattle({builds:[{inscriptions},{}]});assert.deepEqual(E.createBattle(s.initial).fighters[0].build.inscriptions,s.fighters[0].build.inscriptions);assert.equal(s.fighters[1].build.inscriptions[0].atk,0);});
test('面板克制使用与战斗相同的双向属性倍率',()=>{assert.equal(E.typeEffectiveness('自然圣灵','电'),4);assert.equal(E.typeEffectiveness('电','自然圣灵'),.5);});

