test('吸血按实际伤害回复，反伤按实伤且不随粉伤抗性降低',()=>{for(const [id,description,templateText,argsNum,kind] of [[1,'给予对方损伤的一半会回复自己的体力','给予对方损伤的一半会回复自己的体力',0,'drain'],[6,'对方所受伤害的1/4会反弹给自己','对方所受伤害的1/{0}会反弹给自己',1,'recoil']]){const a=snapshot(),b=snapshot(4);a.moves[0].id=910000+id;a.moves[0].effectIds=[id];a.moves[0].description=description;a.effects.push({id,argsNum,template:templateText});const s=battle(a,b);s.fighters[0].hp=1000;const t=E.resolveTurn(s,['wiki:'+(910000+id),'wiki:900003']);const dealt=s.fighters[1].hp-t.fighters[1].hp;assert.equal(t.fighters[0].hp,1000+(kind==='drain'?Math.floor(dealt/2):-Math.floor(dealt/4)));}});
