'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),P=require('../dist/pp-rules.js');
const f=(pp,hp=100)=>({hp,moves:Object.keys(pp),pp:{...pp}}),defs={a:{pp:5},b:{pp:10},c:{pp:20},x:{pp:10},y:{pp:10},z:{pp:10}};
test('公共PP吸取按对应槽位使用实际扣除量，零PP和不足PP不凭空回复',()=>{const a=f({a:0,b:0,c:0}),b=f({x:0,y:1,z:9});const out=P.absorb(a,b,2,defs);assert.deepEqual(b.pp,{x:0,y:0,z:7});assert.deepEqual(a.pp,{a:0,b:1,c:2});assert.equal(out.deducted,3);assert.equal(out.restored,3);assert.deepEqual(out.slots.map(x=>x.deducted),[0,1,2]);});
test('公共PP吸取自身满PP仍扣对手，溢出丢弃且不转给别的槽',()=>{const a=f({a:5,b:9,c:0}),b=f({x:5,y:5,z:0});const out=P.absorb(a,b,2,defs);assert.deepEqual(a.pp,{a:5,b:10,c:0});assert.deepEqual(b.pp,{x:3,y:3,z:0});assert.deepEqual(out.slots.map(x=>x.discarded),[2,1,0]);});
test('公共PP防护与倒下阻止吸取，缺失上限或非法数量原子拒绝',()=>{for(const mode of ['blocked','receiver-dead','donor-dead']){const a=f({a:1}),b=f({x:2});if(mode==='receiver-dead')a.hp=0;if(mode==='donor-dead')b.hp=0;assert.equal(P.absorb(a,b,2,defs,{blocked:mode==='blocked'}).deducted,0);assert.equal(a.pp.a,1);assert.equal(b.pp.x,2);}const a=f({unknown:0}),b=f({x:2});assert.throws(()=>P.absorb(a,b,2,defs));assert.equal(b.pp.x,2);for(const n of [-1,NaN,1.5])assert.throws(()=>P.absorb(a,b,n,defs));});
test('公共PP恢复逐技能饱和，缺少对应接收槽不会恢复其它槽',()=>{const a=f({a:4,b:0,c:20});P.restore(a,defs,2);assert.deepEqual(a.pp,{a:5,b:2,c:20});const receiver=f({a:0}),donor=f({x:2,y:2});P.absorb(receiver,donor,1,defs);assert.deepEqual(receiver.pp,{a:1});assert.deepEqual(donor.pp,{x:1,y:1});});

