 const p=P.configuration(1348);assert.equal(p.status,'confirmed-project-rule');assert.deepEqual(p.candidates,P.pool());assert.deepEqual(P.drawForEffect(1348,2,()=>0),P.drawForEffect(2074,2,()=>0));assert.equal(P.configuration(123456),null);assert.throws(()=>P.drawForEffect(123456,1,()=>assert.fail()),/needs-source/);const config=require('../data/random-pools/effects.json').effects[1348];assert.equal(config.apiHash,'52ea44b4');assert.equal(config.wikiRevision,349330);assert.equal(config.legacyObservation.authoritative,false);assert.equal(config.sharedPoolEffectId,2074);assert.ok(config.historicalInstances.length>0);assert.equal(P.pool().length,38);assert.equal(P.drawForEffect(2074,1,()=>0)[0].duration,1);
