const {test}=require('node:test'),assert=require('node:assert/strict'),E=require('../dist/engine.js'),R=E.WIKI.effectsEngine;
function snap(id,soul=null,ops=[]){return {id,name:'规则测试'+id,type:'普通',base:{maxHp:100,atk:100,def:100,spa:100,spd:100,spe:100},souls:soul?[{id:soul,hash:E.SOULS.registry[soul].sourceHash,description:'已核对规则测试'}]:[],source:{provider:'seerapi'},typeChart:{revision:'test',aliases:{普通:['普通']},rows:{普通:{普通:1}}},effects:ops.map(([id])=>({id,argsNum:R.registry[id].argsNum,template:R.registry[id].template})),missingEffects:[],moves:Array.from({length:4},(_,i)=>({id:id*10+i,name:'测试招'+i,provider:'seerapi',kind:i===0?'physical':'status',type:'普通',power:i===0?60:0,pp:30,priority:0,accuracy:100,alwaysHit:true,critical:'1/16',level:i,fifth:false,effectIds:i===1?ops.map(x=>x[0]):[],effectInstances:i===1?ops.map(([id,args])=>({id,args})):[],description:''}))};}
const key=(id,i)=>'wiki:'+(id*10+i);
function game(a,b=snap(99002),builds=[{},{}]){return E.createBattle({wikiSnapshots:[a,b],criticals:false,seed:'range-test',builds});}
test('两版神耀：能量分层、版本选择、清零与新局隔离',()=>{const a=snap(2987,574,[[860,[2]]]);a.souls.unshift({id:372,hash:E.SOULS.registry[372].sourceHash,description:'普通'});assert.equal(E.WIKI.profileFor(a).soul,574);a.selectedSoulId=372;assert.equal(E.WIKI.profileFor(a).soul,372);let s=game(a);for(let i=0;i<3;i++)s=E.resolveTurn(s,[key(2987,1),key(99002,1)]);assert.equal(s.fighters[0].soulState.energy,5);assert.equal(E.SOULS.trait(s.fighters[0],'ailmentImmune'),true);assert.equal(E.SOULS.trait(s.fighters[0],'attackPriority'),1);assert.equal(E.createBattle(s.initial).fighters[0].soulState.energy,0);a.selectedSoulId=574;s=game(a);for(let i=0;i<3;i++)s=E.resolveTurn(s,[key(2987,1),key(99002,1)]);assert.equal(s.fighters[0].soulState.energy,6);});
test('神耀第五消耗5层、强化6层不消耗，威力加成使用消耗前层数',()=>{for(const [soul,energy] of [[372,5],[574,6]]){const a=snap(2987,soul,[[862,[50]]]);a.moves[0].effectIds=[862];a.moves[0].effectInstances=[{id:862,args:[50]}];a.moves[1].effectIds=[];a.moves[1].effectInstances=[];let s=game(a,undefined,[{overrides:{maxHp:9999}},{overrides:{maxHp:9999}}]);s.fighters[0].soulState.energy=energy;s=E.resolveTurn(s,[key(2987,0),key(99002,1)]);assert.equal(s.fighters[0].soulState.energy,energy===6?6:0);assert.ok(s.turns[0].events.some(e=>e.detail.includes('威力 '+(60+energy*50))));}});
test('凡尔斯仅复制速度学习力和刻印到体力，覆盖最终值仍优先',()=>{const a=snap(2988,373);const s=game(a,undefined,[{evs:{spe:252},inscriptions:[{spe:20},{spe:30},{}]},{}]);assert.equal(s.fighters[0].stats.maxHp,454);const t=game(a,undefined,[{evs:{spe:252},inscriptions:[{spe:50}],overrides:{maxHp:500}},{}]);assert.equal(t.fighters[0].hp,500);});
test('魂印体力比较不把相等归入高低分支，回合开始状态固定',()=>{let s=game(snap(2988,373));s=E.resolveTurn(s,[key(2988,1),key(99002,1)]);assert.equal(s.fighters[0].soulState.highHp,false);assert.equal(s.fighters[0].soulState.lowHp,false);s.fighters[0].hp--;s=E.resolveTurn(s,[key(2988,1),key(99002,1)]);assert.equal(s.fighters[0].soulState.lowHp,true);});
test('斯洛斯受击增伤在下两回合生效并正常到期',()=>{let s=game(snap(2990,369));s=E.resolveTurn(s,[key(2990,1),key(99002,0)]);assert.deepEqual(s.fighters[0].effects.soul369,{start:2,end:3});for(let i=0;i<2;i++)s=E.resolveTurn(s,[key(2990,1),key(99002,1)]);assert.equal(s.fighters[0].effects.soul369,undefined);});
test('圣诞属性回血与千夜无强化吸取不重复结算',()=>{let s=game(snap(2992,368),snap(2999,375));s.fighters[0].hp=100;s.fighters[1].hp=100;s=E.resolveTurn(s,[key(2992,1),key(2999,1)]);assert.equal(s.fighters[0].hp,100);assert.equal(s.fighters[1].hp,300);});
test('多段攻击只扣一次PP，逐段伤害相加且止于击败',()=>{const a=snap(99100,null,[[31,[2,2]]]);a.moves[0].effectIds=[31];a.moves[0].effectInstances=[{id:31,args:[2,2]}];a.moves[1].effectIds=[];a.moves[1].effectInstances=[];let s=game(a,undefined,[{overrides:{maxHp:9999,spe:900}},{overrides:{maxHp:9999}}]);s=E.resolveTurn(s,[key(99100,0),key(99002,1)]);assert.equal(s.fighters[0].pp[key(99100,0)],29);assert.equal(s.turns[0].events.filter(e=>e.detail.includes('威力')).length,2);});
test('结构化回合参数470按已核对语义加一，未知魂印版本拒绝',()=>{const a=snap(99101,null,[[470,[3,30,0]]]);let s=game(a);s=E.resolveTurn(s,[key(99101,1),key(99002,1)]);assert.equal(s.fighters[0].effects['攻击附加异常'].end,4);a.souls=[{id:123456}];assert.equal(E.WIKI.assess(a).supported,false);});

test('先手免伤只限当回合，恢复PP不超过各招上限',()=>{let s=game(snap(99200,null,[[170,[8]],[444,[]]]),undefined,[{overrides:{spe:900}},{}]);s.fighters[0].hp=100;s=E.resolveTurn(s,[key(99200,1),key(99002,0)]);assert.equal(s.fighters[0].hp,100+Math.floor(s.fighters[0].stats.maxHp/8));assert.equal(s.fighters[0].pp[key(99200,1)],30);assert.equal(s.fighters[1].pp[key(99002,0)],28);assert.equal(s.fighters[0].effects['当回合免伤'],undefined);});
test('伤害吸血以实际伤害计算；禁强化阻止后手升能力',()=>{let s=game(snap(99201,null,[[417,[2,50]]]),undefined,[{overrides:{maxHp:9999,spe:900}},{overrides:{maxHp:9999}}]);s.fighters[0].hp=100;s=E.resolveTurn(s,[key(99201,1),key(99002,1)]);assert.equal(s.fighters[0].effects['攻击吸血'].end,3);s=E.resolveTurn(s,[key(99201,0),key(99002,1)]);assert.equal(s.fighters[0].hp,100+Math.floor(s.fighters[0].lastAttackDamage/2));let t=game(snap(99202,null,[[765,[3]]]),snap(99203,null,[[585,[1,1,1,1,1,1]]]),[{overrides:{spe:900}},{}]);t=E.resolveTurn(t,[key(99202,1),key(99203,1)]);assert.ok(Object.values(t.fighters[1].stages).every(n=>n===0));});

