const {test}=require('node:test');const assert=require('node:assert/strict');const D=require('../seerapi.cjs'),R=require('../dist/effect-registry.js'),E=require('../dist/engine.js');
const effect4={id:4,argsNum:3,template:'技能使用成功时，{1}%改变自身{0}等级{2}'};
test('结构化参数直接生成能力效果，重复ID保持独立',()=>{const result=R.compileInstances([{id:4,args:[0,100,1],description:'不用文本反推'},{id:4,args:[4,100,-1]}],[effect4]);assert.equal(result.issue,'');assert.deepEqual(result.operations.map(x=>x.params),[{chance:1,stat:'atk',amount:1,target:'self'},{chance:1,stat:'spe',amount:-1,target:'self'}]);});
test('错误参数数量、未知能力枚举与越界参数拒绝执行',()=>{for(const args of [[0,100],[99,100,1],[0,101,1],[0,100,99],[0,'100',1]])assert.ok(R.compileInstances([{id:4,args}],[effect4]).issue);assert.ok(R.compileInstances([{id:999,args:[]}],[]).issue);});
test('技能转换保留实例参数、分类、概率与未适配机制',()=>{const raw={id:20008,name:'诅咒',power:0,max_pp:10,accuracy:100,priority:0,must_hit:true,crit_rate:null,category:{id:4},atk_num:1,skill_effect:[{effect:{id:4},args:[0,100,1],info:'技能使用成功时，100%改变自身攻击等级+1'}],friend_skill_effect:[],hash:'abc'};const m=D.convertMove(raw,{learning_level:17,is_fifth:false},'普通');assert.equal(m.kind,'status');assert.equal(m.critical,'1/16');assert.equal(m.effectInstances[0].args[2],1);assert.equal(E.WIKI.moveIssue(m,{effects:[effect4],missingEffects:[]}), '');for(const patch of [{atk_num:3},{hide_effect:{id:1}},{friend_skill_effect:[{id:1}]}]){const bad=D.convertMove({...raw,...patch},{},'普通');assert.ok(E.WIKI.moveIssue(bad,{effects:[effect4],missingEffects:[]}));}});
test('属性表只接受完整有限倍率，不偷偷用1补缺项',()=>{const data={count:2,hash:'x',results:[{id:1,name:'草',relations:[{target_type:{id:1},multiple:.5},{target_type:{id:2},multiple:.5}]},{id:2,name:'火',relations:[{target_type:{id:1},multiple:2},{target_type:{id:2},multiple:.5}]}]};assert.equal(D.buildChart(data).rows['火']['草'],2);data.results[1].relations.pop();assert.throws(()=>D.buildChart(data),/缺失/);});
test('核对过的模板同义字可转换，额外文字仍拒绝',()=>{assert.equal(R.compileInstances([{id:1,args:[]}],[{id:1,argsNum:0,template:'给予对方损伤的一半会恢复自己的体力'}]).issue,'');assert.ok(R.compileInstances([{id:1,args:[]}],[{id:1,argsNum:0,template:'给予对方损伤的一半会恢复自己的体力并回满PP'}]).issue);});

test('本批友方目标效果明确延期，保留单挑技能与导出标记',()=>{const raw={id:880001,name:'双语境测试',power:40,max_pp:10,accuracy:100,priority:0,must_hit:true,crit_rate:6.25,category:{id:1},atk_num:1,skill_effect:[],friend_skill_effect:[{effect:{id:201},args:[0,3],info:'为队友恢复体力'}],hash:'test'};const m=D.convertMove(raw,{},'普通',{deferTeamEffects:true});const out=E.WIKI.compile(m,{effects:[],missingEffects:[]});assert.equal(out.issue,'');assert.equal(out.operations.length,0);assert.equal(out.deferred[0].scope,'多精灵待实现');assert.equal(out.deferred[0].effectId,201);});
test('效果534接受模板零参数或已核对隐藏参数10，仍拒绝其他值',()=>{const e={id:534,argsNum:0,template:R.registry[534].template};assert.equal(R.compileInstances([{id:534,args:[10]}],[e]).issue,'');assert.equal(R.compileInstances([{id:534,args:[]}],[e]).issue,'');for(const args of [[20],[10,10]])assert.ok(R.compileInstances([{id:534,args}],[e]).issue);});

