test('延迟决胜等待完整指定回合后结算',()=>{let s=game(snap(99618,null,[[62,[2]]]),undefined,[{overrides:{maxHp:9999}},{overrides:{maxHp:9999}}]);s=E.resolveTurn(s,[key(99618,1),key(99002,1)]);assert.equal(s.finished,false);s=E.resolveTurn(s,[key(99618,2),key(99002,1)]);assert.equal(s.finished,false);s=E.resolveTurn(s,[key(99618,2),key(99002,1)]);assert.equal(s.winner,0);});
test('米斯蒂克首发封属两回合且350惩罚，易伤仅消费一次',()=>{let s=game(snap(99620,424),snap(99621,null,[[585,[1,1,1,1,1,1]]]),[{overrides:{maxHp:5000,spe:900}},{overrides:{maxHp:5000}}]);s=E.resolveTurn(s,[key(99620,1),key(99621,1)]);assert.equal(s.fighters[1].hp,4650);assert.ok(Object.values(s.fighters[1].stages).every(n=>n<=0));assert.equal(s.fighters[1].counts.nextDamageDouble,1);s=E.resolveTurn(s,[key(99620,0),key(99621,2)]);assert.equal(s.fighters[1].counts.nextDamageDouble,1);s=E.resolveTurn(s,[key(99620,1),key(99621,1)]);assert.ok(Object.values(s.fighters[1].stages).some(n=>n>0));});
test('圣甲雷伊低血吸取翻倍，四九增减伤按回合开始体力比较',()=>{let s=game(snap(99622,425),undefined,[{overrides:{maxHp:1000,spe:900,atk:1}},{overrides:{maxHp:1000,def:9999}}]);s.fighters[0].hp=100;s=E.resolveTurn(s,[key(99622,0),key(99002,1)]);assert.equal(s.fighters[0].hp,500);s=game(snap(99623,448),snap(99624,null,[[29,[100]]]),[{overrides:{maxHp:1000,spe:900}},{overrides:{maxHp:2000}}]);s=E.resolveTurn(s,[key(99623,1),key(99624,1)]);assert.equal(s.fighters[0].hp,949);});
test('瑞尔斯攻击吸血量在下一次用招反馈，伙伴面板分支延期',()=>{let s=game(snap(99625,449),undefined,[{overrides:{maxHp:1000,spe:900}},{overrides:{maxHp:1000}}]);s.fighters[0].hp=100;s=E.resolveTurn(s,[key(99625,0),key(99002,1)]);const healed=s.fighters[0].hp-100;assert.ok(healed>0);const before=s.fighters[1].hp;s=E.resolveTurn(s,[key(99625,1),key(99002,1)]);assert.equal(s.fighters[1].hp,before-healed);assert.ok(E.SOULS.registry[456].deferred.length>0);});
test('哈迪斯首回合保命只作用当回合，第二回合追加后不再保命',()=>{let s=game(snap(99626,611),snap(99627,null,[[29,[2000]]]),[{overrides:{maxHp:1000,spe:1}},{overrides:{maxHp:3000,spe:900}}]);s=E.resolveTurn(s,[key(99626,1),key(99627,1)]);assert.equal(s.fighters[0].hp,1);s=E.resolveTurn(s,[key(99626,0),key(99627,1)]);assert.equal(s.turns[1].first,0);assert.ok(s.turns[1].events.some(e=>e.text.includes('哈迪斯保命后追加')));assert.equal(s.fighters[0].hp,0);assert.equal(E.createBattle(s.initial).fighters[0].soulState.hadesRewardRound,undefined);});
