test('皇怒无视反弹异常且不会反弹回星皇',()=>{
  let seen=false;
  for(let i=0;i<30;i++){
    const s=battle({seed:'blind-'+i});s.round=4;s.fighters[0].counts.rageDouble=1;s.fighters[1].effects.reflect={start:1,end:10};
