test('被控制者不扣PP、不触发用招治疗或皇怒',()=>{
  const s=battle();s.round=4;s.fighters[0].ailments['麻痹']=5;s.fighters[0].hp=1000;s.fighters[0].effects.fullHeal={start:4,end:5};
