'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),H=require('./helpers/public-status.cjs');
const {E,S,key,game,turn,apply,timer}=H;
const names=['衰弱','山神守护','易燃','束缚','失神','沉默','臣服','星赐','超频','沸涌','砥砺','星赎','空定','狂信','雷解','魇昧'];
test('扩展16状态公共施加、显式持续、刷新、清除及用户确认默认时长',()=>{
 for(const name of names){const s=game(),f=s.fighters[0];const result=S.attempt(f,name,1,{random:()=>0});if(name==='山神守护'){assert.equal(result.reason,'pve-only');assert.deepEqual(f.ailments,{});continue;}assert.equal(result.reason,'applied');assert.equal(f.ailments[name],name==='衰弱'?3:1);apply(s,0,name,3);assert.equal(f.ailments[name],3);S.attempt(f,name,2,{duration:1});assert.equal(f.ailments[name],name==='衰弱'?4:3);assert.equal(S.clear(f,name),true);assert.equal(f.ailments[name],undefined);apply(s,0,name,2);assert.deepEqual(S.expire(f,1),[]);assert.deepEqual(S.expire(f,name==='衰弱'?3:2),[name]);assert.deepEqual(f.ailments,{});f.hp=0;assert.equal(S.attempt(f,name,3,{duration:2}).reason,'defeated');}
});

