const {test}=require('node:test');const assert=require('node:assert/strict');const {createClient}=require('../wiki-client.cjs');
function harness(fn){let time=100000,calls=[];const c=createClient(async key=>{calls.push({key,time});return fn(key);},{now:()=>time,sleep:async ms=>{time+=ms;},interval:2500,ttl:10000});return {c,calls,advance:ms=>time+=ms};}
test('相同请求合并、成功缓存、不同请求保持最小间隔',async()=>{const h=harness(key=>({status:200,body:{key}}));await Promise.all([h.c.request('a'),h.c.request('a'),h.c.request('b')]);assert.equal(h.calls.length,2);assert.equal(h.calls[1].time-h.calls[0].time,2500);await h.c.request('a');assert.equal(h.calls.length,2);h.advance(10001);await h.c.request('a');assert.equal(h.calls.length,3);});
test('429后队列停止外网访问，Retry-After生效且到期才能恢复',async()=>{let status=429;const h=harness(()=>({status,body:{ok:true},retryAfter:'1200'}));const results=await Promise.allSettled([h.c.request('a'),h.c.request('b')]);assert.ok(results.every(x=>x.status==='rejected'));assert.equal(h.calls.length,1);assert.equal(h.c.status().retryAfter,1200);await assert.rejects(h.c.request('c'));assert.equal(h.calls.length,1);status=200;h.advance(1200001);await h.c.request('a');assert.equal(h.calls.length,2);});
test('403与567不自动重试，冷却期间允许已有缓存',async()=>{for(const status of [403,567]){const h=harness(key=>key==='cached'?{status:200,body:{ok:true}}:{status,body:null});await h.c.request('cached');await assert.rejects(h.c.request('blocked'));await h.c.request('cached');assert.equal(h.calls.length,2);assert.equal(h.c.status().paused,true);}});
test('HTTP200的maxlag仍进入冷却，失败结果不进缓存',async()=>{const h=harness(()=>({status:200,body:{error:{code:'maxlag'}}}));await assert.rejects(h.c.request('a'));assert.equal(h.c.status().cacheEntries,0);assert.equal(h.c.status().retryAfter,60);});
test('Retry-After HTTP日期被遵守',async()=>{const h=harness(()=>({status:503,body:null,retryAfter:new Date(100000+300000).toUTCString()}));await assert.rejects(h.c.request('a'));assert.equal(h.c.status().retryAfter,300);});

