}}');const m=W.parseMove({fields:f,revision:1,title:'技能:30001'});assert.deepEqual(m.effectIds,[4,4]);assert.equal(m.alwaysHit,true);assert.match(m.description,/第二行/);assert.throws(()=>W.parseMove({fields:{...f,'效果ID':'4;run()'}}));});
test('未知精灵、缺失魂印、变化效果ID、缺失效果均阻止开局',()=>{const a=snapshot(3291);assert.equal(E.WIKI.assess(a).supported,true);for(const mutate of [s=>s.id=99999,s=>s.souls=[],s=>s.moves[0].effectIds.push(99999),s=>s.missingEffects=[1098],s=>s.moves[0].revision++,s=>s.souls[0].description+='changed']){const s=structuredClone(a);mutate(s);assert.equal(E.WIKI.assess(s).supported,false);}assert.equal(E.WIKI.assess(a,[30381,30381,30376,25294,25295]).supported,false);});
test('在线基础值参与面板和PP，快照重开与交换双方',()=>{const ss=[snapshot(3291),snapshot(3142)],loadouts=ss.map(s=>E.WIKI.profiles[s.id].defaults);ss[0].base.maxHp=180;ss[0].moves[0].pp=8;const s=E.createBattle({species:['emperor','king'],wikiSnapshots:ss,wikiLoadouts:loadouts});assert.equal(s.fighters[0].stats.maxHp,501);assert.equal(s.fighters[0].pp.emperor5,8);ss[0].base.maxHp=1;assert.equal(s.wikiSnapshots[0].base.maxHp,180);const t=E.resolveTurn(s,['gate','inherit']);assert.equal(t.round,2);const r=E.createBattle(t.initial);assert.equal(r.fighters[0].stats.maxHp,501);assert.equal(r.fighters[0].pp.emperor5,8);const rev=E.createBattle({...s.initial,species:['king','emperor'],wikiSnapshots:s.wikiSnapshots.slice().reverse(),wikiLoadouts:loadouts.slice().reverse()});assert.equal(rev.fighters[0].species,'king');assert.equal(rev.fighters[1].stats.maxHp,501);assert.throws(()=>E.WIKI.prepare([s.wikiSnapshots[0],s.wikiSnapshots[0]],[loadouts[0],loadouts[0]]),/同种/);});
test('搜索参数拒绝 Wiki 查询注入和空输入',async()=>{for(const q of ['','[[分类:魂印]]','a|limit=500','x'.repeat(41)])await assert.rejects(W.search(q));await assert.rejects(W.species('../secrets'));});
test('在线开局验证失败时回滚全局资料，不影响旧对局',()=>{const before=E.MOVES,base={...E.SPECIES.emperor.base},ss=[snapshot(3291),snapshot(3142)];ss[0].base.maxHp=400;assert.throws(()=>E.createBattle({species:['emperor','king'],wikiSnapshots:ss,wikiLoadouts:ss.map(s=>E.WIKI.profiles[s.id].defaults),builds:[{level:0},{}]}));assert.equal(E.MOVES,before);assert.deepEqual(E.SPECIES.emperor.base,base);});

