const {test}=require('node:test'),assert=require('node:assert/strict'),E=require('../dist/engine.js'),R=E.WIKI.effectsEngine;
function snap(id,soul=null,ops=[]){return {id,name:'规则测试'+id,type:'普通',base:{maxHp:100,atk:100,def:100,spa:100,spd:100,spe:100},souls:soul?[{id:soul,hash:E.SOULS.registry[soul].sourceHash,description:'已核对规则测试'}]:[],source:{provider:'seerapi'},typeChart:{revision:'test',aliases:{普通:['普通']},rows:{普通:{普通:1}}},effects:ops.map(([id])=>({id,argsNum:R.registry[id].argsNum,template:R.registry[id].template})),missingEffects:[],moves:Array.from({length:4},(_,i)=>({id:id*10+i,name:'测试招'+i,provider:'seerapi',kind:i===0?'physical':'status',type:'普通',power:i===0?60:0,pp:30,priority:0,accuracy:100,alwaysHit:true,critical:'1/16',level:i,fifth:false,effectIds:i===1?ops.map(x=>x[0]):[],effectInstances:i===1?ops.map(([id,args])=>({id,args})):[],description:''}))};}
const key=(id,i)=>'wiki:'+(id*10+i);
function game(a,b=snap(99002),builds=[{},{}]){return E.createBattle({wikiSnapshots:[a,b],criticals:false,seed:'range-test',builds});}
test('武魂印：攻击与固伤减半，必定命中不受降命中影响',()=>{const a=snap(99810,null,[[29,[200]]]),b=snap(99811,402),plain=snap(99811);const builds=[{overrides:{maxHp:9999,spe:900}},{overrides:{maxHp:9999}}];let s=game(a,b,builds);s=E.resolveTurn(s,[key(99810,1),key(99811,1)]);assert.equal(s.fighters[1].hp,9899);const reduced=E.resolveTurn(game(a,b,builds),[key(99810,0),key(99811,1)]),normal=E.resolveTurn(game(a,plain,builds),[key(99810,0),key(99811,1)]);assert.equal(reduced.fighters[0].lastAttackDamage,Math.floor(normal.fighters[0].lastAttackDamage/2));assert.ok(reduced.fighters[0].lastAttackDamage>0);});
test('武魂印：非必中属性招也受命中降低，技能失误不执行强化',()=>{const a=snap(99812,null,[[585,[1,1,1,1,1,1]]]),b=snap(99813,402);a.moves[1].alwaysHit=false;let missed=0;for(let i=0;i<30;i++){const s=E.createBattle({...game(a,b).initial,seed:'wusheng-'+i});const t=E.resolveTurn(s,[key(99812,1),key(99813,1)]);if(t.fighters[0].stages.atk===0)missed++;}assert.ok(missed>0&&missed<30);});
test('623仅清弱成功才登记下回合必暴，不在当前回合生效',()=>{const a=snap(99814,null,[[623,[1]]]);let s=game(a);let t=E.resolveTurn(s,[key(99814,1),key(99002,1)]);assert.equal(t.fighters[0].effects['必定暴击'],undefined);s.fighters[0].stages.atk=-2;t=E.resolveTurn(s,[key(99814,1),key(99002,1)]);assert.equal(t.fighters[0].stages.atk,0);assert.deepEqual(t.fighters[0].effects['必定暴击'],{start:2,end:2});});
test('烧伤枚举2接入470与609，719未击败才附加烧伤',()=>{const a=snap(99815,null,[[470,[3,100,2]],[609,[2]],[719,[100,2]]]);a.moves[0].effectIds=[609,719];a.moves[0].effectInstances=[{id:609,args:[2]},{id:719,args:[100,2]}];a.moves[1].effectIds=[470];a.moves[1].effectInstances=[{id:470,args:[3,100,2]}];let s=game(a,undefined,[{overrides:{maxHp:9999,spe:900}},{overrides:{maxHp:9999}}]);s=E.resolveTurn(s,[key(99815,1),key(99002,1)]);assert.equal(s.fighters[0].effects['攻击附加异常'].ailment,'烧伤');s.fighters[1].ailments['烧伤']=9;s=E.resolveTurn(s,[key(99815,0),key(99002,1)]);assert.ok(s.turns.at(-1).events.some(e=>e.detail.includes('威力 120')));assert.ok(s.turns.at(-1).events.some(e=>e.text.includes('陷入烧伤')));const c={t:{hp:0},random:()=>0,ailment(){throw Error('不应对倒下目标施加烧伤');}};R.registry[719].execute(c,[100,2]);});
